import fs from 'node:fs/promises';
import path from 'node:path';
import { WorkerAttemptExecutor, observeNativeWorkerResources, nativeSourceCleanupResultSchema,
  sha256Digest, type WorkerAttemptOperation } from '@kubeclaw/worker-core';
import { validateWorkerResourceContractV3, type WorkerAttemptEnvelopeV3 } from '@kubeclaw/pipeline-worker-core-contract';
import { validateBusterPreparationSettings } from '../../../common/plugin-runtime/foundation/config/swarm.ts';
import { assertPreparationCleanupEffects, type PreparationCleanupEffects } from './preparation-cleanup-binding.ts';
import { preparationSourceDirectory } from './preparation-source.ts';

function assigned(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`BUSTER_PREPARATION_ASSIGNED_ENV_REQUIRED:${name}`);
  return value;
}

async function readEnvelope(maximumBytes: number): Promise<WorkerAttemptEnvelopeV3> {
  const chunks: Buffer[] = [];
  let bytes = 0;
  for await (const chunk of process.stdin) {
    bytes += chunk.byteLength;
    if (bytes > maximumBytes) throw new Error('BUSTER_PREPARATION_ENVELOPE_LIMIT');
    chunks.push(Buffer.from(chunk));
  }
  const value: unknown = JSON.parse(Buffer.concat(chunks, bytes).toString('utf8'));
  validateWorkerResourceContractV3('workerAttemptEnvelope', value);
  return value as WorkerAttemptEnvelopeV3;
}

async function removeOwnedData(root: string, effects: PreparationCleanupEffects, signal: AbortSignal): Promise<void> {
  const directory = preparationSourceDirectory(root, effects.admissionId);
  const gate = path.dirname(directory);
  const stat = await fs.lstat(gate);
  if (!stat.isDirectory() || stat.uid !== 0 || stat.gid !== effects.gate.preparationUid
    || (stat.mode & 0o7777) !== 0o1770 || stat.dev !== effects.gate.device || stat.ino !== effects.gate.inode) {
    throw new Error('BUSTER_PREPARATION_CLEANUP_GATE_CHANGED');
  }
  let data;
  try { data = await fs.lstat(directory); }
  catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error; }
  if (data) {
    if (!effects.data || !data.isDirectory() || data.dev !== effects.data.device
      || data.ino !== effects.data.inode || data.uid !== effects.data.uid) {
      throw new Error('BUSTER_PREPARATION_CLEANUP_SOURCE_CHANGED');
    }
    signal.throwIfAborted();
    await fs.rm(directory, { recursive: true });
  }
  // Absence is valid only under the durable association for this exact gate/effect.
  // The parent independently verifies the sealed result before removing its marker.
  const handle = await fs.open(gate, 'r');
  try { await handle.sync(); } finally { await handle.close(); }
  signal.throwIfAborted();
}

async function main(): Promise<void> {
  const maximumBytes = Number(assigned('BUSTER_PREPARATION_ASSIGNED_INPUT_BYTES'));
  if (!Number.isSafeInteger(maximumBytes) || maximumBytes < 1) throw new Error('BUSTER_PREPARATION_ENVELOPE_LIMIT');
  const encoded = assigned('BUSTER_PREPARATION_ASSIGNED_CLEANUP');
  if (Buffer.byteLength(encoded) > maximumBytes) throw new Error('BUSTER_PREPARATION_ENVELOPE_LIMIT');
  const association = JSON.parse(encoded) as { effects: PreparationCleanupEffects; settings: unknown };
  if (Object.keys(association).sort().join(',') !== 'effects,settings') throw new Error('BUSTER_PREPARATION_CLEANUP_ASSOCIATION_INVALID');
  assertPreparationCleanupEffects(association.effects);
  validateBusterPreparationSettings(association.settings);
  const effects = association.effects;
  if (process.getuid?.() !== effects.gate.preparationUid || process.getgid?.() !== effects.gate.preparationUid) {
    throw new Error('BUSTER_PREPARATION_SLOT_INVALID');
  }
  const envelope = await readEnvelope(maximumBytes);
  if (envelope.operation.contractId !== 'kubeclaw.native-source-cleanup@1'
    || envelope.operation.values.effectsDigest !== sha256Digest(effects)) throw new Error('BUSTER_PREPARATION_CLEANUP_ASSOCIATION_INVALID');
  const cancellation = new AbortController();
  const cancel = () => cancellation.abort(new Error('BUSTER_PREPARATION_CANCELLED'));
  process.once('SIGINT', cancel);
  process.once('SIGTERM', cancel);
  let finished = false;
  const operation: WorkerAttemptOperation<WorkerAttemptEnvelopeV3> = {
    prepare() { return undefined; },
    async execute(context) {
      await removeOwnedData(assigned('BUSTER_PREPARATION_ASSIGNED_SOURCE_ROOT'), effects,
        AbortSignal.any([context.signal, cancellation.signal]));
      finished = true;
      return { summary: 'Owned unpublished source cleanup completed', evidence: [], exitCode: 0, signal: null,
        specialistResult: { ...nativeSourceCleanupResultSchema,
          values: { reconciliationDigest: sha256Digest(envelope.operation.values) } } };
    },
    async terminate() { cancel(); },
    async cleanup() { if (!finished) throw new Error('BUSTER_PREPARATION_SOURCE_RECONCILIATION_REQUIRED'); },
    async measure() {
      const resources = observeNativeWorkerResources(assigned('KUBECLAW_NATIVE_SCOPE'));
      return { cpuTimeMs: { status: 'observed', value: Math.ceil(resources.cpuTimeMicroseconds / 1000) },
        maximumMemoryBytes: { status: 'observed', value: resources.maximumMemoryBytes },
        maximumTasks: { status: 'observed', value: resources.maximumTasks } };
    },
  };
  try {
    const result = await new WorkerAttemptExecutor({ envelope, operation, signal: cancellation.signal,
      retainLogs: false, receiptNamespace: 'buster-source-cleanup-provisional' }).execute();
    process.stdout.write(JSON.stringify(result));
  } finally {
    process.removeListener('SIGINT', cancel);
    process.removeListener('SIGTERM', cancel);
  }
}

await main();

import { assertPreparationSlot } from './preparation-slots.ts';
import { Socket } from 'node:net';
import {
  NativeWorkerControlChannel, WorkerAttemptExecutor, observeNativeWorkerResources, sha256Digest,
  type WorkerAttemptOperation,
} from '@kubeclaw/worker-core';
import { validateWorkerResourceContractV3, type WorkerAttemptEnvelopeV3 } from '@kubeclaw/pipeline-worker-core-contract';
import { validateBusterPreparationSettings } from '../../../common/plugin-runtime/foundation/config/swarm.ts';
import { readPreparationInput, materializePreparedSource, preparationSourceDirectory } from './preparation-source.ts';
import { PreparationHostInput, preparationHostChannelLimits } from './preparation-host-channel.ts';
import { stagePreparationInput, stagedInputMetadata, assertBusterInput, wireDigest, type BusterInputReference } from './preparation-input.ts';
import { preparedPlanHeader, preparationDigest } from './preparation-header.ts';

async function readEnvelope(maximumBytes: number): Promise<WorkerAttemptEnvelopeV3> {
  const chunks: Buffer[] = [];
  let count = 0;
  for await (const chunk of process.stdin) {
    count += chunk.byteLength;
    if (count > maximumBytes) throw new Error('BUSTER_PREPARATION_ENVELOPE_LIMIT');
    chunks.push(Buffer.from(chunk));
  }
  const envelope: unknown = JSON.parse(Buffer.concat(chunks, count).toString('utf8'));
  validateWorkerResourceContractV3('workerAttemptEnvelope', envelope);
  return envelope as WorkerAttemptEnvelopeV3;
}

function environment(name: string): string {
  const value = process.env[name];
  if (!value) throw new Error(`BUSTER_PREPARATION_ASSIGNED_ENV_REQUIRED:${name}`);
  return value;
}

async function assignedPhase() {
  const maximumInputBytes = Number(environment('BUSTER_PREPARATION_ASSIGNED_INPUT_BYTES'));
  if (!Number.isSafeInteger(maximumInputBytes) || maximumInputBytes < 1 || maximumInputBytes > 2_147_483_647) {
    throw new Error('BUSTER_PREPARATION_ENVELOPE_LIMIT');
  }
  const envelope = await readEnvelope(maximumInputBytes);
  const settings = validateBusterPreparationSettings(envelope.operation.values.settings);
  const admissionId = envelope.operation.values.admissionId;
  const preparationUid = envelope.operation.values.preparationUid;
  assertPreparationSlot(preparationUid);
  if (process.getuid?.() !== preparationUid || process.getgid?.() !== preparationUid) throw new Error('BUSTER_PREPARATION_SLOT_INVALID');
  if (typeof admissionId !== 'string' || Object.keys(envelope.operation.values).sort().join(',') !== 'admissionId,phase,preparationUid,settings'
    || envelope.operation.contractId !== 'kubeclaw.buster-preparation@1') throw new Error('BUSTER_PREPARATION_OPERATION_INVALID');
  const phase = envelope.operation.values.phase as { kind?: unknown; input?: unknown };
  if (!phase || !['stage', 'extract'].includes(String(phase.kind))
    || Object.keys(phase).sort().join(',') !== (phase.kind === 'stage' ? 'kind' : 'input,kind')) {
    throw new Error('BUSTER_PREPARATION_PHASE_INVALID');
  }
  const sourceRoot = environment('BUSTER_PREPARATION_ASSIGNED_SOURCE_ROOT');
  preparationSourceDirectory(sourceRoot, admissionId);
  return { envelope, settings, admissionId, phase, sourceRoot };
}

async function main(): Promise<void> {
  const scope = environment('KUBECLAW_NATIVE_SCOPE');
  const { envelope, settings, admissionId, phase, sourceRoot } = await assignedPhase();
  const channel = new NativeWorkerControlChannel(new Socket({ fd: 3, readable: true, writable: true, allowHalfOpen: true }), preparationHostChannelLimits(settings));
  const input = new PreparationHostInput(channel, admissionId);
  const cancellation = new AbortController();
  const cancel = () => cancellation.abort(new Error('BUSTER_PREPARATION_CANCELLED'));
  process.once('SIGINT', cancel);
  process.once('SIGTERM', cancel);
  let allocated = false;
  let materialized = false;
  const operation: WorkerAttemptOperation<WorkerAttemptEnvelopeV3> = {
    prepare() { return undefined; },
    async execute(context) {
      const signal = AbortSignal.any([context.signal, cancellation.signal]);
      const { job, wire } = await readPreparationInput(input.chunks(), settings, {
        trustedSourceAuthority: environment('BUSTER_PREPARATION_ASSIGNED_SOURCE_AUTHORITY'),
        sourceAttestationPublicKey: environment('BUSTER_PREPARATION_ASSIGNED_SOURCE_PUBLIC_KEY'),
      }, signal);
      let values: unknown;
      let schemaId: string;
      if (phase.kind === 'stage') {
        const staged = stagedInputMetadata(job, wire, admissionId, envelope.attemptSpecDigest, settings);
        const accepted = await input.admission(staged);
        values = accepted ? await stagePreparationInput(staged, wire, sourceRoot, signal, () => { allocated = true; }) : { declined: true };
        schemaId = accepted ? 'buster-staged-input-result.v1' : 'buster-declined-input-result.v1';
      } else {
        const retained = phase.input as BusterInputReference;
        assertBusterInput(retained, preparedPlanHeader(job));
        if (wire.byteLength !== retained.wireBytes || wireDigest(wire) !== retained.wireDigest
          || preparationDigest(preparedPlanHeader(job)) !== retained.headerDigest) {
          throw new Error('BUSTER_PREPARATION_RETAINED_INPUT_MISMATCH');
        }
        values = await materializePreparedSource(job, admissionId, envelope.attemptSpecDigest,
          sourceRoot, environment('BUSTER_PREPARATION_ASSIGNED_TAR'), settings, signal, () => { allocated = true; });
        schemaId = 'buster-preparation-result.v1';
      }
      materialized = true;
      return { summary: 'Owned source phase completed', evidence: [], exitCode: 0, signal: null,
        specialistResult: { schemaId, schemaDigest: sha256Digest({ schemaVersion: schemaId }),
          values: JSON.parse(JSON.stringify(values)) } };
    },
    async terminate() { cancel(); channel.destroy(); },
    async cleanup() {
      if (allocated && !materialized) throw new Error('BUSTER_PREPARATION_SOURCE_RECONCILIATION_REQUIRED');
    },
    // Retained successful source is an intended output; partial source needs separate quiescent reconciliation.
    async measure() {
      const resources = observeNativeWorkerResources(scope);
      return {
        cpuTimeMs: { status: 'observed', value: Math.ceil(resources.cpuTimeMicroseconds / 1000) },
        maximumMemoryBytes: { status: 'observed', value: resources.maximumMemoryBytes },
        maximumTasks: { status: 'observed', value: resources.maximumTasks },
      };
    },
  };
  try {
    const result = await new WorkerAttemptExecutor({ envelope, operation, signal: cancellation.signal,
      retainLogs: false, receiptNamespace: 'buster-preparation-provisional' }).execute();
    process.stdout.write(JSON.stringify(result));
  } finally {
    channel.destroy();
    process.removeListener('SIGINT', cancel);
    process.removeListener('SIGTERM', cancel);
  }
}

await main();

import { validatePreparationCleanupChain } from './preparation-cleanup-validation.ts';
import type { PreparationCleanupAssociation } from './preparation-cleanup-binding.ts';
import { assertHistoricalImportDescriptor, type HistoricalImportDescriptor } from './preparation-historical-reference.ts';
import { validateWorkerResourceContractV3, type WorkerAttemptEnvelopeV3 } from '@kubeclaw/pipeline-worker-core-contract';
import { assertPreparationSlot, type PreparationSlot } from './preparation-slots.ts';
import { assertStagedInput, type StagedAdmission } from './preparation-input.ts';
import type { PreparationGateBinding } from './preparation-gate.ts';
import { assertPreparedSourceShape, preparationDigest, type PreparedSourceReference } from './preparation-header.ts';

export interface SourceReservation {
  readonly admissionId: string;
  readonly attemptSpecDigest: string;
  readonly envelope: WorkerAttemptEnvelopeV3;
  readonly slot: PreparationSlot;
  readonly slotReleased: boolean;
  readonly input: StagedAdmission | null;
  readonly parentInputId: string | null;
  readonly extractionGeneration: number;
  readonly previousExtractionDigest: string | null;
  readonly emptyGateResultDigest: string | null;
  readonly historicalDescriptor: HistoricalImportDescriptor | null;
  readonly groupMetadataBytes: number;
  readonly groupRecords: number;
  readonly groupReceiptDigest: string | null;
  readonly phase: 'historical-reserved' | 'retained-historical' | 'empty-gate-reclaiming' | 'staging' | 'retained-input' | 'reserved' | 'prepared' | 'published' | 'repository-released' | 'released';
  readonly gate: PreparationGateBinding | null;
  readonly bytes: number;
  readonly entries: number;
  readonly source: PreparedSourceReference | null;
  readonly cleanup: readonly PreparationCleanupAssociation[];
}
export interface SourceLedger {
  readonly schemaVersion: 'buster-preparation-ledger.v1';
  readonly reservations: readonly SourceReservation[];
}
export const empty: SourceLedger = { schemaVersion: 'buster-preparation-ledger.v1', reservations: [] };
export function terminalMetadataProjection(item: SourceReservation): SourceReservation {
  if (item.phase === 'released') return item;
  const digest = `sha256:${'f'.repeat(64)}`;
  if (item.historicalDescriptor !== null) return { ...item, phase: 'historical-reserved', slotReleased: false, groupReceiptDigest: digest,
    gate: item.gate ?? { preparationUid: item.slot, device: Number.MAX_SAFE_INTEGER, inode: Number.MAX_SAFE_INTEGER, markerDigest: digest } };
  if (item.parentInputId === null) return { ...item, phase: 'empty-gate-reclaiming', slotReleased: false, emptyGateResultDigest: digest,
    gate: item.gate ?? { preparationUid: item.slot, device: Number.MAX_SAFE_INTEGER, inode: Number.MAX_SAFE_INTEGER, markerDigest: digest } };
  return { ...item, phase: 'repository-released', gate: item.gate ?? {
    preparationUid: item.slot, device: Number.MAX_SAFE_INTEGER, inode: Number.MAX_SAFE_INTEGER, markerDigest: digest,
  }, source: item.source ?? {
    schemaVersion: 'buster-prepared-source.v1', admissionId: item.admissionId, preparationUid: item.slot,
    jobId: `job:${'f'.repeat(64)}`, requestDigest: digest, headerDigest: digest,
    archiveDigest: digest, archiveBytes: Number.MAX_SAFE_INTEGER, attemptSpecDigest: item.attemptSpecDigest,
  } };
}

const phases = ['historical-reserved', 'retained-historical', 'empty-gate-reclaiming', 'staging',
  'retained-input', 'reserved', 'prepared', 'published', 'repository-released', 'released'];
const releasedSlotPhases = ['retained-historical', 'retained-input', 'published', 'repository-released', 'released'];
const digest = (value: unknown) => typeof value === 'string' && /^sha256:[a-f0-9]{64}$/u.test(value);
const nonnegative = (value: unknown) => typeof value === 'number' && Number.isSafeInteger(value) && value >= 0;
function invalid(): never { throw new Error('BUSTER_PREPARATION_LEDGER_INVALID'); }

function validateReservationShape(item: SourceReservation): void {
  const keys = ['admissionId', 'attemptSpecDigest', 'bytes', 'cleanup', 'emptyGateResultDigest', 'entries', 'envelope', 'extractionGeneration', 'gate',
    'groupMetadataBytes', 'groupReceiptDigest', 'groupRecords', 'historicalDescriptor', 'input', 'parentInputId',
    'phase', 'previousExtractionDigest', 'slot', 'slotReleased', 'source'];
  if (!item || Object.keys(item).sort().join(',') !== keys.sort().join(',')
    || typeof item.admissionId !== 'string' || !/^[a-f0-9]{32}$/u.test(item.admissionId) || !digest(item.attemptSpecDigest)
    || !phases.includes(item.phase) || ![item.bytes, item.entries, item.groupMetadataBytes, item.groupRecords].every(nonnegative)) invalid();
  if (typeof item.slotReleased !== 'boolean' || (item.slotReleased && !releasedSlotPhases.includes(item.phase))) invalid();
  if (item.parentInputId !== null && !digest(item.parentInputId)) invalid();
}

function validateReservationEnvelope(item: SourceReservation): void {
  assertPreparationSlot(item.slot);
  validateWorkerResourceContractV3('workerAttemptEnvelope', item.envelope);
  const values = item.envelope.operation.values;
  if (values.preparationUid !== item.slot || values.admissionId !== item.admissionId
    || item.envelope.attemptSpecDigest !== item.attemptSpecDigest
    || item.envelope.operation.contractId !== 'kubeclaw.buster-preparation@1'
    || Object.keys(values).sort().join(',') !== 'admissionId,phase,preparationUid,settings') invalid();
  const phase = values.phase as { kind?: unknown; input?: unknown; descriptor?: unknown };
  if (!phase || typeof phase !== 'object') invalid();
  if (item.historicalDescriptor !== null) {
    if (phase.kind !== 'historical' || preparationDigest(phase.descriptor) !== preparationDigest(item.historicalDescriptor)) invalid();
  } else if (item.parentInputId !== null) {
    if (phase.kind !== 'extract' || preparationDigest(phase.input) !== item.parentInputId) invalid();
  } else if (phase.kind !== 'stage') invalid();
}

function validateGate(item: SourceReservation): void {
  if (item.gate === null) return;
  if (Object.keys(item.gate).sort().join(',') !== 'device,inode,markerDigest,preparationUid'
    || item.gate.preparationUid !== item.slot || ![item.gate.device, item.gate.inode].every(nonnegative)
    || !digest(item.gate.markerDigest)) invalid();
}

function validateStagedReservation(item: SourceReservation): void {
  if (item.emptyGateResultDigest !== null && !digest(item.emptyGateResultDigest)) invalid();
  if (item.phase === 'empty-gate-reclaiming' && (!item.emptyGateResultDigest || !item.gate || item.source !== null)) invalid();
  if (item.input !== null) {
    assertStagedInput(item.input.input, item.input.job);
    if (item.input.input.admissionId !== item.admissionId || item.input.input.preparationUid !== item.slot
      || item.input.input.attemptSpecDigest !== item.attemptSpecDigest) invalid();
  }
  if (item.phase === 'retained-input' && (item.input === null || item.gate === null || !item.slotReleased)) invalid();
}

function validateHistoricalReservation(item: SourceReservation): void {
  if (item.groupReceiptDigest !== null && !digest(item.groupReceiptDigest)) invalid();
  if (item.historicalDescriptor === null) {
    if (item.groupMetadataBytes !== 0 || item.groupRecords !== 0 || item.groupReceiptDigest !== null
      || ['historical-reserved', 'retained-historical'].includes(item.phase)) invalid();
    return;
  }
  assertHistoricalImportDescriptor(item.historicalDescriptor);
  if (item.input !== null || item.parentInputId !== null || item.source !== null) invalid();
  if (item.phase === 'retained-historical' && (!item.gate || !item.groupReceiptDigest || !item.slotReleased)) invalid();
  if (!['historical-reserved', 'retained-historical', 'released'].includes(item.phase)) invalid();
}

function validateSourceReservation(item: SourceReservation): void {
  if (item.source !== null) {
    assertPreparedSourceShape(item.source);
    if (item.source.admissionId !== item.admissionId || item.source.attemptSpecDigest !== item.attemptSpecDigest
      || item.source.preparationUid !== item.slot || item.parentInputId === null) invalid();
  }
  if (item.phase === 'reserved' && item.source !== null) invalid();
  if (['prepared', 'published', 'repository-released'].includes(item.phase) && (item.source === null || item.gate === null)) invalid();
  if (item.phase === 'released') {
    if (item.bytes !== 0 || item.entries !== 0 || !item.slotReleased) invalid();
    if (item.emptyGateResultDigest === null && !item.cleanup.at(-1)?.resultDigest) invalid();
  } else if (item.bytes < 1 || item.entries < 1) invalid();
}


function validateExtractionGeneration(item: SourceReservation, byEnvelope: ReadonlyMap<string, SourceReservation>,
  generations: Set<string>): void {
  if (item.parentInputId === null) {
    if (item.extractionGeneration !== 0 || item.previousExtractionDigest !== null) invalid();
    return;
  }
  if (!Number.isSafeInteger(item.extractionGeneration) || item.extractionGeneration < 1) invalid();
  const key = `${item.parentInputId}:${item.extractionGeneration}`;
  if (generations.has(key)) invalid();
  generations.add(key);
  if (item.extractionGeneration === 1) {
    if (item.previousExtractionDigest !== null) invalid();
    return;
  }
  if (!digest(item.previousExtractionDigest)) invalid();
  const previous = byEnvelope.get(item.previousExtractionDigest!);
  if (!previous || previous.phase !== 'released' || previous.parentInputId !== item.parentInputId
    || previous.extractionGeneration + 1 !== item.extractionGeneration) invalid();
}

export function validateSourceLedger(state: SourceLedger): void {
  if (!state || state.schemaVersion !== empty.schemaVersion || Object.keys(state).sort().join(',') !== 'reservations,schemaVersion'
    || !Array.isArray(state.reservations)) invalid();
  const identities = new Set<string>();
  const occupied = new Set<number>();
  const inputs = new Set<string>();
  for (const item of state.reservations) {
    validateReservationShape(item);
    validateReservationEnvelope(item);
    validateGate(item);
    validatePreparationCleanupChain(item.cleanup, item.envelope, item.gate);
    validateStagedReservation(item);
    validateHistoricalReservation(item);
    validateSourceReservation(item);
    if (identities.has(item.admissionId) || (!item.slotReleased && occupied.has(item.slot))
      || (item.parentInputId !== null && item.phase !== 'released' && inputs.has(item.parentInputId))) invalid();
    identities.add(item.admissionId);
    if (!item.slotReleased) occupied.add(item.slot);
    if (item.parentInputId !== null && item.phase !== 'released') inputs.add(item.parentInputId);
  }
  const byEnvelope = new Map(state.reservations.map(item => [preparationDigest(item.envelope), item]));
  const generations = new Set<string>();
  for (const item of state.reservations) validateExtractionGeneration(item, byEnvelope, generations);
}

import { preparationCleanupMetadataCapacity, type PreparationCleanupAssociation } from './preparation-cleanup-binding.ts';
import { resolveHistoricalInput, type HistoricalStagedAdmission } from './preparation-historical-reference.ts';
import { assertHistoricalImportDescriptor, type HistoricalImportDescriptor } from './preparation-historical-reference.ts';
import { empty, terminalMetadataProjection, validateSourceLedger, type SourceReservation, type SourceLedger } from './preparation-ledger-state.ts';
import { canonicalJson } from '@kubeclaw/pipeline-observability-contract';
import { type WorkerAttemptEnvelopeV3, type WorkerProfileV3 } from '@kubeclaw/pipeline-worker-core-contract';
import { assertStagedInput, assertBusterInput, type StagedAdmission, type BusterStagedAdmission } from './preparation-input.ts';
import { gateReservation, stagedInputReservation, extractedSourceReservation } from './preparation-reservations.ts';
import { preparationDigest } from './preparation-header.ts';
import { preparationEnvelope } from './preparation-envelope.ts';
import { preparationSlots } from './preparation-slots.ts';
import path from 'node:path';
import { readDurableState, withDurableStoreLock, writeDurableState } from '@kubeclaw/plugin-foundation/observability/durable-delivery';
import type { PreparationGateBinding } from './preparation-gate.ts';
import type { BusterPreparationSettings } from '../../../common/plugin-runtime/foundation/config/swarm.ts';
import { type PreparedSourceReference } from './preparation-header.ts';

/** Root-owned metadata. Failed or uncertain lifetimes keep their full reservation. */
export class PreparationSourceLedger {
  readonly #file: string;
  readonly #settings: BusterPreparationSettings;

  constructor(root: string, settings: BusterPreparationSettings) {
    this.#file = path.join(root, 'source-ledger', 'state.json');
    this.#settings = structuredClone(settings);
  }

  async reserve(admissionId: string, profile: WorkerProfileV3, now: Date): Promise<WorkerAttemptEnvelopeV3> {
    profile = structuredClone(profile);
    now = new Date(now);
    if (!/^[a-f0-9]{32}$/u.test(admissionId)) throw new Error('BUSTER_PREPARATION_RESERVATION_INVALID');
    return withDurableStoreLock(this.#file, async () => {
      const state = await this.#read();
      const existing = state.reservations.find(item => item.admissionId === admissionId);
      if (existing) return structuredClone(existing.envelope);
      const occupied = new Set(state.reservations.filter(item => !item.slotReleased).map(item => item.slot));
      const slot = preparationSlots.slice(0, this.#settings.maximumActivePreparations).find(candidate => !occupied.has(candidate));
      if (slot === undefined) throw new Error('BUSTER_PREPARATION_SLOT_CAPACITY');
      const envelope = preparationEnvelope(admissionId, profile, this.#settings, now, slot, { kind: 'stage' });
      const reservation: SourceReservation = {
        admissionId, attemptSpecDigest: envelope.attemptSpecDigest, envelope, slot, slotReleased: false,
        phase: 'staging', emptyGateResultDigest: null, historicalDescriptor: null, groupMetadataBytes: 0, groupRecords: 0, groupReceiptDigest: null, input: null, parentInputId: null, extractionGeneration: 0, previousExtractionDigest: null, source: null, cleanup: [], gate: null, ...gateReservation(this.#settings),
      };
      await this.#write({ ...state, reservations: [...state.reservations, reservation] });
      return structuredClone(envelope);
    });
  }

  async reserveHistorical(importId: string, profile: WorkerProfileV3, now: Date,
    descriptor: HistoricalImportDescriptor): Promise<WorkerAttemptEnvelopeV3> {
    descriptor = structuredClone(descriptor);
    profile = structuredClone(profile);
    now = new Date(now);
    assertHistoricalImportDescriptor(descriptor);
    return withDurableStoreLock(this.#file, async () => {
      const state = await this.#read();
      const existing = state.reservations.find(item => item.admissionId === importId);
      if (existing) {
        if (preparationDigest(existing.historicalDescriptor) !== preparationDigest(descriptor)) {
          throw new Error('BUSTER_PREPARATION_RESERVATION_CONFLICT');
        }
        return structuredClone(existing.envelope);
      }
      const occupied = new Set(state.reservations.filter(item => !item.slotReleased).map(item => item.slot));
      const slot = preparationSlots.slice(0, this.#settings.maximumActivePreparations).find(value => !occupied.has(value));
      if (slot === undefined) throw new Error('BUSTER_PREPARATION_SLOT_CAPACITY');
      const envelope = preparationEnvelope(importId, profile, this.#settings, now, slot,
        { kind: 'historical', descriptor: structuredClone(descriptor) });
      const reservation: SourceReservation = {
        admissionId: importId, attemptSpecDigest: envelope.attemptSpecDigest, envelope, slot, slotReleased: false,
        phase: 'historical-reserved', historicalDescriptor: structuredClone(descriptor),
        groupMetadataBytes: 0, groupRecords: 0, groupReceiptDigest: null, emptyGateResultDigest: null,
        input: null, parentInputId: null, extractionGeneration: 0, previousExtractionDigest: null, source: null, cleanup: [], gate: null, ...gateReservation(this.#settings),
      };
      await this.#write({ ...state, reservations: [...state.reservations, reservation] });
      return structuredClone(envelope);
    });
  }

  async reserveHistoricalStorage(importId: string, required: {
    bytes: number; entries: number; metadataBytes: number; records: number;
  }): Promise<void> {
    required = structuredClone(required);
    if (!Object.values(required).every(value => Number.isSafeInteger(value) && value >= 0)) {
      throw new Error('BUSTER_PREPARATION_RESERVATION_INVALID');
    }
    await this.#transition(importId, current => {
      if (current.phase !== 'historical-reserved' || current.slotReleased
        || required.bytes < current.bytes || required.entries < current.entries
        || required.metadataBytes < current.groupMetadataBytes || required.records < current.groupRecords) {
        throw new Error('BUSTER_PREPARATION_RESERVATION_CONFLICT');
      }
      return { ...current, bytes: required.bytes, entries: required.entries,
        groupMetadataBytes: required.metadataBytes, groupRecords: required.records };
    });
  }

  async retainedHistorical(importId: string, groupReceiptDigest: string): Promise<void> {
    if (!/^sha256:[a-f0-9]{64}$/u.test(groupReceiptDigest)) throw new Error('BUSTER_PREPARATION_GROUP_RECEIPT_INVALID');
    await this.#transition(importId, current => {
      if (!['historical-reserved', 'retained-historical'].includes(current.phase) || !current.gate
        || (current.groupReceiptDigest !== null && current.groupReceiptDigest !== groupReceiptDigest)) {
        throw new Error('BUSTER_PREPARATION_GROUP_RECEIPT_INVALID');
      }
      return { ...current, phase: 'retained-historical', slotReleased: true, groupReceiptDigest };
    });
  }

  /** Reserve the exact durable wire before the host is allowed to write it. */
  async stageInput(staged: StagedAdmission): Promise<void> {
    staged = structuredClone(staged);
    assertStagedInput(staged.input, staged.job);
    await this.#transition(staged.input.admissionId, current => {
      if (current.phase !== 'staging' || current.attemptSpecDigest !== staged.input.attemptSpecDigest
        || current.slot !== staged.input.preparationUid || !current.gate
        || (current.input && preparationDigest(current.input) !== preparationDigest(staged))) {
        throw new Error('BUSTER_PREPARATION_INPUT_BINDING_INVALID');
      }
      return { ...current, input: structuredClone(staged), ...stagedInputReservation(staged, this.#settings) };
    });
  }

  /** Caller has verified the successful native result and revoked the now-quiescent gate. */
  async retainInput(staged: StagedAdmission): Promise<void> {
    staged = structuredClone(staged);
    await this.#transition(staged.input.admissionId, current => {
      if (!['staging', 'retained-input'].includes(current.phase) || !current.gate
        || preparationDigest(current.input) !== preparationDigest(staged)) {
        throw new Error('BUSTER_PREPARATION_INPUT_BINDING_INVALID');
      }
      return { ...current, phase: 'retained-input', slotReleased: true };
    });
  }

  /** Same immutable input always replays its originally accepted extraction envelope. */
  async reserveExtraction(admissionId: string, staged: BusterStagedAdmission,
    profile: WorkerProfileV3, now: Date): Promise<WorkerAttemptEnvelopeV3> {
    staged = structuredClone(staged);
    profile = structuredClone(profile);
    now = new Date(now);
    assertBusterInput(staged.input, staged.job);
    return withDurableStoreLock(this.#file, async () => {
      const state = await this.#read();
      const key = preparationDigest(staged.input);
      const inputReference = staged.input;
      if (inputReference.schemaVersion === 'buster-historical-input.v1') {
        const group = state.reservations.find(item => item.admissionId === inputReference.importId);
        if (group?.phase !== 'retained-historical' || !group.slotReleased || !group.groupReceiptDigest) {
          throw new Error('BUSTER_PREPARATION_RETAINED_INPUT_REQUIRED');
        }
        await resolveHistoricalInput(path.dirname(path.dirname(this.#file)),
          staged as HistoricalStagedAdmission, this.#settings.maximumMetadataBytes, group.groupReceiptDigest);
      } else {
        const input = state.reservations.find(item => item.admissionId === inputReference.admissionId);
        if (input?.phase !== 'retained-input' || !input.slotReleased
          || preparationDigest(input.input) !== preparationDigest(staged)) {
          throw new Error('BUSTER_PREPARATION_RETAINED_INPUT_REQUIRED');
        }
      }
      const generations = state.reservations.filter(item => item.parentInputId === key);
      const existing = generations.sort((a, b) => b.extractionGeneration - a.extractionGeneration)[0];
      if (existing && existing.phase !== 'released') return structuredClone(existing.envelope);
      if (state.reservations.some(item => item.admissionId === admissionId)) {
        throw new Error('BUSTER_PREPARATION_RESERVATION_CONFLICT');
      }
      const occupied = new Set(state.reservations.filter(item => !item.slotReleased).map(item => item.slot));
      const slot = preparationSlots.slice(0, this.#settings.maximumActivePreparations).find(value => !occupied.has(value));
      if (slot === undefined) throw new Error('BUSTER_PREPARATION_SLOT_CAPACITY');
      const envelope = preparationEnvelope(admissionId, profile, this.#settings, now, slot,
        { kind: 'extract', input: structuredClone(staged.input) });
      const reservation: SourceReservation = {
        admissionId, attemptSpecDigest: envelope.attemptSpecDigest, envelope, slot, slotReleased: false,
        phase: 'reserved', emptyGateResultDigest: null, historicalDescriptor: null, groupMetadataBytes: 0, groupRecords: 0, groupReceiptDigest: null, input: null, parentInputId: key, extractionGeneration: (existing?.extractionGeneration ?? 0) + 1,
        previousExtractionDigest: existing ? preparationDigest(existing.envelope) : null, source: null, cleanup: [], gate: null,
        ...extractedSourceReservation(staged, this.#settings),
      };
      await this.#write({ ...state, reservations: [...state.reservations, reservation] });
      return structuredClone(envelope);
    });
  }

  /** Bind positive no-source terminal evidence before removing even root-only metadata. */
  async beginEmptyGateReclaim(admissionId: string, resultDigest: string): Promise<void> {
    if (!/^sha256:[a-f0-9]{64}$/u.test(resultDigest)) throw new Error('BUSTER_PREPARATION_EMPTY_GATE_PROOF_INVALID');
    await this.#transition(admissionId, current => {
      if (!['staging', 'reserved', 'empty-gate-reclaiming'].includes(current.phase)
        || current.source !== null || !current.gate
        || (current.emptyGateResultDigest !== null && current.emptyGateResultDigest !== resultDigest)) {
        throw new Error('BUSTER_PREPARATION_EMPTY_GATE_PROOF_INVALID');
      }
      return { ...current, phase: 'empty-gate-reclaiming', emptyGateResultDigest: resultDigest };
    });
  }

  /** Publication intent never releases the identity; call after quiescence and durable gate revocation. */
  async releasePublishedSlot(source: PreparedSourceReference): Promise<void> {
    source = structuredClone(source);
    await this.#transition(source.admissionId, current => {
      if (current.phase !== 'published' || JSON.stringify(current.source) !== JSON.stringify(source)) {
        throw new Error('BUSTER_PREPARATION_SLOT_RELEASE_INVALID');
      }
      return { ...current, slotReleased: true };
    });
  }

  async bindGate(admissionId: string, binding: PreparationGateBinding): Promise<void> {
    binding = structuredClone(binding);
    await this.#transition(admissionId, current => {
      if (current.gate !== null && JSON.stringify(current.gate) !== JSON.stringify(binding)) {
        throw new Error('BUSTER_PREPARATION_GATE_CONFLICT');
      }
      return { ...current, gate: structuredClone(binding) };
    });
  }

  async published(source: PreparedSourceReference): Promise<void> {
    source = structuredClone(source);
    await this.#transition(source.admissionId, current => {
      if (!current.gate || !['prepared', 'published'].includes(current.phase)
        || JSON.stringify(current.source) !== JSON.stringify(source)) throw new Error('BUSTER_PREPARATION_PUBLICATION_INVALID');
      return { ...current, phase: 'published' };
    });
  }

  async prepared(source: PreparedSourceReference): Promise<void> {
    source = structuredClone(source);
    await this.#transition(source.admissionId, current => {
      if (current.attemptSpecDigest !== source.attemptSpecDigest) throw new Error('BUSTER_PREPARATION_RESERVATION_CONFLICT');
      if (current.phase !== 'reserved') {
        if (JSON.stringify(current.source) !== JSON.stringify(source)) throw new Error('BUSTER_PREPARATION_RESERVATION_CONFLICT');
        return current;
      }
      return { ...current, source: structuredClone(source), phase: 'prepared' };
    });
  }

  /** Caller must first verify the exact native cleanup receipt and retained archive identity. */
  async repositoryReleased(admissionId: string, archiveBytes: number, metadataBytes: number): Promise<void> {
    if (![archiveBytes, metadataBytes].every(value => Number.isSafeInteger(value) && value >= 0)) {
      throw new Error('BUSTER_PREPARATION_RELEASE_INVALID');
    }
    await this.#transition(admissionId, current => {
      if (!current.source || current.source.archiveBytes !== archiveBytes || current.phase === 'released') {
        throw new Error('BUSTER_PREPARATION_RELEASE_INVALID');
      }
      const bytes = archiveBytes + metadataBytes + 6 * this.#settings.sourceEntryReservationBytes;
      if (bytes > current.bytes) throw new Error('BUSTER_PREPARATION_RELEASE_INVALID');
      return { ...current, phase: 'repository-released', bytes, entries: 6 };
    });
  }

  /** Never called merely because a child exited; exact quiescence and owned absence are prerequisites. */
  async released(admissionId: string): Promise<void> {
    await this.#transition(admissionId, current => ({ ...current, phase: 'released', slotReleased: true, bytes: 0, entries: 0 }));
  }

  /** The association is fsynced before any cleanup process can remove owned source. */
  async reserveCleanup(admissionId: string, association: PreparationCleanupAssociation): Promise<void> {
    association = structuredClone(association);
    await this.#transition(admissionId, current => {
      if (current.slotReleased || !['staging', 'reserved'].includes(current.phase) || !current.gate) {
        throw new Error('BUSTER_PREPARATION_CLEANUP_INELIGIBLE');
      }
      const existing = current.cleanup.find(item => item.envelope.attemptId === association.envelope.attemptId);
      if (existing) {
        if (preparationDigest(existing) !== preparationDigest(association)) throw new Error('BUSTER_PREPARATION_CLEANUP_CONFLICT');
        return current;
      }
      return { ...current, cleanup: [...current.cleanup, association] };
    });
  }

  /** A result digest is write-once. Failed predecessor receipts remain bound on retry. */
  async recordCleanupResult(admissionId: string, envelopeDigest: string, resultDigest: string): Promise<void> {
    await this.#transition(admissionId, current => {
      const index = current.cleanup.findIndex(item => preparationDigest(item.envelope) === envelopeDigest);
      const association = current.cleanup[index];
      if (!association || (association.resultDigest !== null && association.resultDigest !== resultDigest)) {
        throw new Error('BUSTER_PREPARATION_CLEANUP_CONFLICT');
      }
      const cleanup = [...current.cleanup];
      cleanup[index] = { ...association, resultDigest };
      return { ...current, cleanup };
    });
  }

  async reservations(): Promise<readonly SourceReservation[]> {
    return withDurableStoreLock(this.#file, async () => structuredClone((await this.#read()).reservations));
  }

  async #transition(admissionId: string, update: (value: SourceReservation) => SourceReservation): Promise<void> {
    await withDurableStoreLock(this.#file, async () => {
      const state = await this.#read();
      const index = state.reservations.findIndex(item => item.admissionId === admissionId);
      if (index < 0) throw new Error('BUSTER_PREPARATION_RESERVATION_MISSING');
      const reservations = [...state.reservations];
      reservations[index] = update(reservations[index]!);
      await this.#write({ ...state, reservations });
    });
  }

  async #read(): Promise<SourceLedger> {
    const state = await readDurableState<SourceLedger>(this.#file, empty, this.#settings.maximumMetadataBytes);
    validateSourceLedger(state);
    return state;
  }


  async #write(state: SourceLedger): Promise<void> {
    validateSourceLedger(state);
    const bytes = state.reservations.reduce((sum, item) => sum + item.bytes, 0);
    const entries = state.reservations.reduce((sum, item) => sum + item.entries, 0);
    // Every admitted slot reserves its future terminal reference before native launch.
    const metadata = Math.max(Buffer.byteLength(canonicalJson(state)), Buffer.byteLength(canonicalJson({ ...state,
      reservations: state.reservations.map(terminalMetadataProjection) })))
      + state.reservations.filter(item => item.phase === 'staging' && item.input === null).length
        * (this.#settings.maximumHeaderBytes + this.#settings.maximumInputBytes)
      + state.reservations.reduce((sum, item) => sum + item.groupMetadataBytes, 0)
      + state.reservations.filter(item => !item.slotReleased).length
        * preparationCleanupMetadataCapacity(this.#settings.maximumInputBytes);
    if (state.reservations.length + state.reservations.reduce((sum, item) => sum + item.groupRecords + item.cleanup.length
      + (item.slotReleased ? 0 : 1), 0) > this.#settings.maximumRecords || metadata > this.#settings.maximumMetadataBytes
      || !Number.isSafeInteger(bytes) || bytes > this.#settings.maximumSourceBytes
      || !Number.isSafeInteger(entries) || entries > this.#settings.maximumSourceEntries) {
      throw new Error('BUSTER_PREPARATION_SOURCE_CAPACITY');
    }
    await writeDurableState(this.#file, state);
  }
}

import { assertBusterInput, type BusterStagedAdmission } from './preparation-input.ts';
import type { PreparedPlanJob } from './preparation-header.ts';
import type { NativeWorkerControlChannel } from '@kubeclaw/worker-core';
import { decodePreparationMessage, encodePreparationMessage, PreparationIngress,
  type PreparationMessage } from './preparation-channel.ts';
import type { PreparedAdmission } from './preparation-client.ts';

interface Admission {
  readonly ingress: PreparationIngress;
  readonly cancellation: AbortController;
  readonly work: Promise<void>;
  ended: boolean;
  decision: ReturnType<typeof Promise.withResolvers<boolean>> | null;
}

/** Fixed preparation protocol. Root never accepts a path, command or identity from the service. */
export async function servePreparationRequests(channel: NativeWorkerControlChannel, options: {
  readonly maximumActivePreparations: number;
  readonly maximumRequestBytes: number;
  readonly prepare: (ingress: PreparationIngress, signal: AbortSignal,
    admit: (job: PreparedPlanJob) => Promise<boolean>) => Promise<BusterStagedAdmission | null>;
  readonly extract: (staged: BusterStagedAdmission, signal: AbortSignal) => Promise<PreparedAdmission>;
}): Promise<void> {
  const admissions = new Map<string, Admission>();
  const pending = new Set<Promise<void>>();
  const failure = async (requestId: string, error: unknown) => {
    const message = error instanceof Error ? error.message.slice(0, 256).toWellFormed() : 'BUSTER_PREPARATION_FAILED';
    await channel.send(encodePreparationMessage('failure', requestId, Buffer.from(message)));
  };
  const begin = async (requestId: string, staged?: BusterStagedAdmission) => {
    if (admissions.has(requestId)) throw new Error('BUSTER_PREPARATION_REQUEST_REPEATED');
    if (admissions.size >= options.maximumActivePreparations) {
      await failure(requestId, new Error('BUSTER_PREPARATION_ADMISSION_FULL'));
      return;
    }
    const ingress = new PreparationIngress(options.maximumRequestBytes);
    const cancellation = new AbortController();
    const work = Promise.resolve().then(async () => {
      try {
        const prepared = staged ? await options.extract(staged, cancellation.signal)
          : await options.prepare(ingress, cancellation.signal, async job => {
            const admission = admissions.get(requestId);
            if (!admission || admission.decision) throw new Error('BUSTER_PREPARATION_DECISION_STATE_INVALID');
            const decision = Promise.withResolvers<boolean>();
            void decision.promise.catch(() => {});
            admission.decision = decision;
            await channel.send(encodePreparationMessage('validated', requestId, Buffer.from(JSON.stringify(job))));
            return decision.promise;
          });
        await channel.send(encodePreparationMessage('result', requestId, Buffer.from(JSON.stringify(prepared))));
      } catch (error) {
        await failure(requestId, error);
      } finally {
        ingress.fail(new Error('BUSTER_PREPARATION_FINISHED'));
        admissions.delete(requestId);
      }
    });
    admissions.set(requestId, { ingress, cancellation, work, ended: Boolean(staged), decision: null });
    pending.add(work);
    void work.finally(() => pending.delete(work)).catch(() => channel.destroy());
    if (!staged) await channel.send(encodePreparationMessage('ready', requestId));
  };
  try {
    for await (const raw of channel.messages()) {
      const message = decodePreparationMessage(raw);
      if (message.kind === 'begin') await begin(message.admissionId);
      else if (message.kind === 'extract') {
        const staged = JSON.parse(message.content.toString('utf8')) as BusterStagedAdmission;
        assertBusterInput(staged.input, staged.job);
        await begin(message.admissionId, staged);
      } else await receiveBody(channel, admissions, message);
    }
  } finally {
    for (const admission of admissions.values()) {
      const error = new Error('BUSTER_PREPARATION_SERVICE_LOST');
      admission.cancellation.abort(error);
      admission.ingress.fail(error);
      admission.decision?.reject(error);
    }
    await Promise.allSettled(pending);
    channel.destroy();
  }
}

async function receiveBody(channel: NativeWorkerControlChannel, admissions: Map<string, Admission>,
  message: PreparationMessage): Promise<void> {
  const admission = admissions.get(message.admissionId);
  // A rejected request may have a cancellation already in transit.
  if (message.kind === 'cancel') {
    const error = new Error('BUSTER_PREPARATION_CANCELLED');
    admission?.cancellation.abort(error);
    admission?.ingress.fail(error);
    admission?.decision?.reject(error);
    return;
  }
  if (message.kind === 'proceed' || message.kind === 'decline') {
    if (!admission?.ended || !admission.decision) throw new Error('BUSTER_PREPARATION_DECISION_STATE_INVALID');
    admission.decision.resolve(message.kind === 'proceed');
    admission.decision = null;
    return;
  }
  if (!admission || admission.ended) throw new Error('BUSTER_PREPARATION_REQUEST_UNKNOWN');
  if (message.kind === 'end') {
    admission.ended = true;
    admission.ingress.end();
  } else if (message.kind === 'bytes') {
    // A native failure rejects the pending chunk. Its work already sends failure.
    try { await admission.ingress.write(message.content); }
    catch (error) {
      admission.cancellation.abort(error);
      admission.ingress.fail(error);
      return;
    }
    await channel.send(encodePreparationMessage('ack', message.admissionId));
  } else throw new Error('BUSTER_PREPARATION_PHASE_INVALID');
}

import { assertPreparationSlot } from './preparation-slots.ts';
import fs from 'node:fs/promises';
import path from 'node:path';
import {
  remotePlanJobDigest, remotePlanJobId, repositoryArchiveBytes, resolvedTestPlanDigest,
  validatePipelineTestGateContract, verifySourceSnapshotAttestation, type RemotePlanJobV1,
} from '@kubeclaw/pipeline-test-gate-contract';
import type { BusterPreparationSettings } from '../../../common/plugin-runtime/foundation/config/swarm.ts';
import { ensureDirectoryDurable } from '@kubeclaw/plugin-foundation/observability/durable-delivery';
import {
  preparedPlanHeader, preparationDigest, assertPreparedSource,
  type PreparedPlanJob, type PreparedSourceReference,
} from './preparation-header.ts';
import { safeExtract } from './preparation-archive.ts';

export interface PreparationAuthority {
  readonly trustedSourceAuthority: string;
  readonly sourceAttestationPublicKey: string;
}
export interface PreparedSource {
  readonly job: PreparedPlanJob;
  readonly source: PreparedSourceReference;
}

/** Called inside the owned host. The caller streams chunks, never a decoded job. */
export async function readPreparationInput(input: AsyncIterable<Uint8Array>,
  settings: BusterPreparationSettings, authority: PreparationAuthority, signal: AbortSignal): Promise<{ readonly job: RemotePlanJobV1; readonly wire: Buffer }> {
  const chunks: Buffer[] = [];
  let count = 0;
  for await (const bytes of input) {
    signal.throwIfAborted();
    count += bytes.byteLength;
    if (count > settings.maximumRequestBytes) throw new Error('BUSTER_REMOTE_REQUEST_SIZE_EXCEEDED');
    chunks.push(Buffer.from(bytes));
  }
  signal.throwIfAborted();
  const wire = Buffer.concat(chunks, count);
  let value: unknown;
  try { value = JSON.parse(wire.toString('utf8')); }
  catch (error) { throw new Error('BUSTER_REMOTE_REQUEST_INVALID', { cause: error }); }
  // Contract validation performs the original canonical base64 and archive digest checks.
  validatePipelineTestGateContract('remotePlanJob', value);
  const job = value as RemotePlanJobV1;
  if (job.repositoryArchive.sizeBytes > settings.maximumArchiveBytes
    || job.repositoryArchive.data.length > Math.ceil(settings.maximumArchiveBytes / 3) * 4) {
    throw new Error('BUSTER_REMOTE_ARCHIVE_SIZE_EXCEEDED');
  }
  if (!verifySourceSnapshotAttestation(job.sourceSnapshot,
    authority.trustedSourceAuthority, authority.sourceAttestationPublicKey)) throw new Error('BUSTER_SOURCE_ATTESTATION_INVALID');
  if (remotePlanJobId(job.idempotencyKey) !== job.jobId) throw new Error('BUSTER_REMOTE_JOB_ID_INVALID');
  if (resolvedTestPlanDigest(job.plan) !== job.plan.planDigest) throw new Error('BUSTER_REMOTE_PLAN_DIGEST_MISMATCH');
  if (remotePlanJobDigest(job) !== job.requestDigest) throw new Error('BUSTER_REMOTE_REQUEST_DIGEST_MISMATCH');
  return { job, wire };
}

export function preparationSourceDirectory(root: string, admissionId: string): string {
  if (typeof admissionId !== 'string' || !/^[a-f0-9]{32}$/u.test(admissionId) || !path.isAbsolute(root) || path.resolve(root) !== root || root === '/') {
    throw new Error('BUSTER_PREPARATION_PATH_INVALID');
  }
  return path.join(root, admissionId, 'data');
}

async function writeExclusive(file: string, bytes: Uint8Array): Promise<void> {
  const handle = await fs.open(file, 'wx', 0o600);
  try { await handle.writeFile(bytes); await handle.chmod(0o640); await handle.sync(); }
  finally { await handle.close(); }
}

/** Bounded preview before any source directory allocation. */
export function preparedSourceMetadata(job: RemotePlanJobV1, admissionId: string,
  attemptSpecDigest: string, settings: BusterPreparationSettings): PreparedSource {
  const header = preparedPlanHeader(job);
  if (Buffer.byteLength(JSON.stringify(header)) > settings.maximumHeaderBytes) throw new Error('BUSTER_PREPARATION_HEADER_LIMIT');
  const preparationUid = process.getuid?.();
  assertPreparationSlot(preparationUid);
  if (process.getgid?.() !== preparationUid) throw new Error('BUSTER_PREPARATION_SLOT_INVALID');
  const source: PreparedSourceReference = {
    schemaVersion: 'buster-prepared-source.v1', admissionId, preparationUid, jobId: header.jobId,
    requestDigest: header.requestDigest, headerDigest: preparationDigest(header),
    archiveDigest: header.repositoryArchive.contentDigest, archiveBytes: header.repositoryArchive.sizeBytes,
    attemptSpecDigest,
  };
  assertPreparedSource(source, header);
  const prepared = { job: header, source };
  if (Buffer.byteLength(JSON.stringify(prepared)) + 4 * settings.maximumInputBytes > settings.maximumResultBytes) {
    throw new Error('BUSTER_PREPARATION_RESULT_CAPACITY');
  }
  return prepared;
}

/** Files remain unpublished until the parent records the authoritative native receipt. */
export async function materializePreparedSource(job: RemotePlanJobV1, admissionId: string,
  attemptSpecDigest: string, root: string, tarExecutable: string,
  settings: BusterPreparationSettings, signal: AbortSignal, onAllocated: () => void): Promise<PreparedSource> {
  const prepared = preparedSourceMetadata(job, admissionId, attemptSpecDigest, settings);
  const metadata = Buffer.from(JSON.stringify(prepared));
  signal.throwIfAborted();
  const directory = preparationSourceDirectory(root, admissionId);
  await fs.mkdir(directory, { mode: 0o700 });
  onAllocated();
  await writeExclusive(path.join(directory, 'owner.json'), Buffer.from(JSON.stringify({
    schemaVersion: 'buster-preparation-owner.v1', admissionId, attemptSpecDigest,
    claimId: `claim-${admissionId}`, generation: 1,
  })));
  const repository = path.join(directory, 'repository');
  await ensureDirectoryDurable(repository);
  const archive = path.join(directory, 'repository.tar.gz');
  await writeExclusive(archive, repositoryArchiveBytes(job.repositoryArchive));
  await safeExtract(tarExecutable, archive, repository, settings, signal);
  await synchronizeRepository(repository, signal);
  await writeExclusive(path.join(directory, 'source.json'), metadata);
  await fs.chmod(path.join(directory, 'source.json'), 0o444);
  await fs.chmod(directory, 0o755);
  for (const item of [directory, path.dirname(directory)]) {
    const handle = await fs.open(item, 'r');
    try { await handle.sync(); } finally { await handle.close(); }
  }
  return prepared;
}

async function synchronizeRepository(directory: string, signal: AbortSignal): Promise<void> {
  const entries = await fs.opendir(directory);
  for await (const entry of entries) {
    signal.throwIfAborted();
    const file = path.join(directory, entry.name);
    if (entry.isDirectory()) await synchronizeRepository(file, signal);
    else if (entry.isFile()) {
      const handle = await fs.open(file, 'r');
      try {
        const stat = await handle.stat();
        await handle.chmod(0o644 | (stat.mode & 0o111 ? 0o111 : 0));
        await handle.sync();
      } finally { await handle.close(); }
    } else throw new Error('BUSTER_REMOTE_ARCHIVE_TYPE_DENIED');
  }
  const handle = await fs.open(directory, 'r');
  try { await handle.chmod(0o755); await handle.sync(); } finally { await handle.close(); }
}
